def get(name):return pd.read_csv(R/'tables'/name)
def table(d,cols):
 f=d[[c for c in cols+['n','stocks','events']if c in d]].copy();f=f.rename(columns={'n':'Obs','stocks':'股票数','events':'事件段数'})
 for c in ['Obs','股票数','事件段数']:
  if c not in f:f[c]='不适用'
  else:f[c]=f[c].map(lambda x:f'{int(x):,}'if pd.notna(x)and isinstance(x,(int,float,np.number))else x)
 f=f.astype(object).where(pd.notna(f),'NA')
 return f.to_markdown(index=False,floatfmt='.6g',missingval='NA')
def effects(d,p='wild_p'):
 return '；'.join(f"{r['metric']}={r['beta_x100']:.4g}（{p}={r.get(p,float('nan')):.4g}）"for r in d.to_dict('records'))
def sec(title,conclusion,d,cols,worst):return f'## {title}\n\n结论：{conclusion}\n\n'+table(d,cols)+'\n\n最不利事实：'+worst+'\n\n'
